{
  "technical_and_design_decisions": [
    "For U1: Wiki content will be stored as Markdown files in a /docs directory at the root of the project repository, with Git tags aligned to code release tags for versioning.",
    "For U2: A new spring.hadoop.namenode-address configuration property will be added to the default application configuration, with a fallback to the standard default HDFS namenode URI to maintain backward compatibility.",
    "For U3: The jdbchdfs batch job will be modified to support a passthrough.mode boolean flag that disables chunk processing and uses direct stream read/write when enabled, to eliminate batch overhead.",
    "For U4: The execution context decoupling fix will be implemented directly in Spring Batch core, separating serialization logic from the job launch lifecycle, and XD will be upgraded to the corresponding Spring Batch release to inherit the fix, removing the XD-2486 workaround.",
    "For U5: The XD module deployment logic will be updated to validate Java Config-based custom job modules by scanning for @Configuration classes containing @Bean job definitions, and the deployment error will be fixed by ensuring job registration occurs immediately after module upload.",
    "For U6: A generic PluggableTaskExecutor SPI will be designed to abstract underlying runtime execution, with the Receptor API implemented as the first concrete implementation, and runtime selection will be handled via configuration properties using dependency injection.",
    "For U7: A mandatory shortDescription field will be added to the module metadata schema, and all existing module documentation will be updated to include this field, with the field exposed via the public module registry API.",
    "For U8: The existing XD shell processor will be reused to execute Python scripts loaded from HDFS, instead of building a new processor, to reduce development effort and maintain consistency with existing shell command functionality. A new hdfs-script-source component will be added to load scripts from HDFS and pass them to the shell processor."
  ],
  "assumptions": [
    "Development team has full access to the project Git repository, target HDFS cluster, Spring Batch core codebase, and XD module registry for implementation and testing.",
    "Existing unit and integration test suites for Spring Batch, XD modules, and HDFS integration are available and can be extended to cover new functionality.",
    "The Hadoop namenode address provided in the configuration will be a valid, accessible URI for the target HDFS environment.",
    "The Spring Batch release containing the execution context decoupling fix will be available for XD to upgrade to within the development timeline, and the upstream fix will be accepted after standard community review.",
    "A compatible Python runtime is installed and accessible on all XD-on-Cloud Foundry instances where the shell processor will execute.",
    "All existing module documentation is stored in a central, version-controlled location that can be updated to include the required shortDescription field.",
    "The XD module deployment environment has the necessary permissions to upload and register custom job modules."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Convert and migrate wiki content to project repo",
      "activity_description": "Extract all existing wiki content, convert to Markdown format, resolve broken links/formatting issues, and organize into a logical folder structure under the project repo's /docs directory.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "Configure Git versioning for wiki content",
      "activity_description": "Set up CI pipeline integration to tag wiki content with corresponding code releases, and add contribution guidelines for wiki updates in the repo.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Add Hadoop namenode config property",
      "activity_description": "Add a spring.hadoop.namenode-address property to the default application.yml configuration file, with a default value matching the standard HDFS namenode URI, and add input validation for the property.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A4",
      "activity_name": "Update HDFS client to use configured namenode address",
      "activity_description": "Modify the HDFS client bean configuration to use the new spring.hadoop.namenode-address property instead of hardcoded values, and add unit tests to verify correct configuration application.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5",
      "activity_name": "Add passthrough mode to jdbchdfs batch job",
      "activity_description": "Add a passthrough.enabled boolean configuration flag to the jdbchdfs batch job, implement logic to switch between chunk-oriented processing and direct stream passthrough when the flag is enabled.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "Add integration tests for jdbchdfs passthrough mode",
      "activity_description": "Write integration tests to validate passthrough mode functionality for HDFS read/write operations, and confirm existing chunk mode behavior remains unchanged.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement execution context decoupling fix in Spring Batch core",
      "activity_description": "Refactor Spring Batch core to separate ExecutionContext serialization/deserialization logic from the job launch lifecycle, eliminating ClassLoader and serialization errors, and add unit tests for the refactored components.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A8",
      "activity_name": "Submit and merge execution context fix to Spring Batch upstream",
      "activity_description": "Prepare a pull request for the Spring Batch execution context decoupling fix, address community review feedback, and merge the fix into the Spring Batch core codebase.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "Upgrade XD Spring Batch dependency and refactor workaround",
      "activity_description": "Upgrade XD's Spring Batch dependency to the new release containing the execution context fix, remove the existing XD-2486 workaround code, and run full regression tests to validate no functionality is broken.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Update module upload logic for Java Config job modules",
      "activity_description": "Modify XD's module upload and validation logic to detect Java Config-based custom job modules (via @Configuration classes with @Bean job definitions) and register them correctly during deployment.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A11",
      "activity_name": "Fix job deployment error and add validation",
      "activity_description": "Resolve the 'job does not exist' post-deployment error by ensuring job registration occurs immediately after module upload, and add pre-deployment validation to catch missing job definitions early.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A12",
      "activity_name": "Design PluggableTaskExecutor SPI for XD runtime",
      "activity_description": "Define the public API for the generic PluggableTaskExecutor SPI, including required methods for task submission, status tracking, and result retrieval, ensuring agnosticism to underlying runtime implementations (Lattice, Diego, etc.).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A13",
      "activity_name": "Implement Receptor API as SPI implementation",
      "activity_description": "Implement the PluggableTaskExecutor interface using the existing Receptor API, including integration with the Receptor client for task management, and add unit tests for the implementation.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A14",
      "activity_name": "Add runtime SPI selection configuration",
      "activity_description": "Add configuration properties to allow users to select the desired SPI implementation at runtime, and update documentation to explain SPI configuration options.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A15",
      "activity_name": "Update module metadata schema for shortDescription",
      "activity_description": "Add a mandatory shortDescription field to the module metadata JSON schema, update the module registry API to require and store this field during module upload, and add validation for the field format.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A16",
      "activity_name": "Update all module documentation with shortDescription",
      "activity_description": "Review all existing module documentation, add a concise shortDescription for each module, and validate that all descriptions comply with the updated schema requirements.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A17",
      "activity_name": "Implement HDFS Python script source reader",
      "activity_description": "Add a new hdfs-script-source component that reads Python script files from HDFS using the configured namenode address, and passes the script content to the existing XD shell processor for execution.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A18",
      "activity_name": "Add integration tests for HDFS Python script execution",
      "activity_description": "Write integration tests to verify Python scripts stored on HDFS are correctly loaded, executed by the shell processor, results are returned to the XD stream, and error handling for missing/invalid scripts works as expected.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A19",
      "activity_name": "Create developer documentation for new features",
      "activity_description": "Write comprehensive developer documentation covering all implemented functionality, including configuration guides, usage examples, and migration steps for existing users.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 135
  }
}

